entries[405061] = { ["name"] = "Erkenntnis von Nasz'uro", ["text"] = "Eure ermächtigten Zauber aktivieren die Ordnungsmagie im Inneren und entfesseln eine Sphäre der Ordnung. Diese sucht einen mächtigen Verbündeten und erhöht seinen Primärwert um 29 und seine Geschwindigkeit um 53 . Hält 10 Sek. lang an." }
