entries[405063] = { ["name"] = "Instabile Essenz", ["text"] = "Unbegrenzte Reichweite\nSofort\nThadrion erfüllt Spielercharaktere mit instabiler Energie, die alle 2 Sek. 3 Arkanschaden verursacht und mit der Zeit an Intensität gewinnt.\n\nBei Entfernung verschmilzt die Energie kurzzeitig und explodiert dann, was Spielercharakteren innerhalb von 12 Metern 60 Arkanschaden zufügt und ein Vorkommen von ' Unberechenbarer Überrest ' hinterlässt.\n\nEine verbleibende Spur der Energie springt dann auf einen Spielercharakter in der Nähe über und belegt ihn mit 'Instabile Essenz'." }
entries[405064] = { ["name"] = "Verdunkelter Elementarkern", ["text"] = "40 Meter ReichweiteWirken in 1 sek. 1.5 min Abklingzeit\nWirft einen kleinen verdunkelten Elementarkern an einen Zielort, der 3911 Schattenflammenschaden verursacht, der gleichmäßig auf alle Gegner verteilt wird." }
entries[405065] = { ["name"] = "Erkenntnis von Nasz'uro", ["text"] = "50 Meter Reichweite\nSofort\nEure ermächtigten Zauber aktivieren die Ordnungsmagie im Inneren und entfesseln eine Sphäre der Ordnung. Diese sucht einen mächtigen Verbündeten und erhöht seinen Primärwert um 29 und seine Geschwindigkeit um 53 . Hält 10 Sek. lang an." }
entries[405066] = { ["name"] = "Summender Kugelkern", ["text"] = "Baut langsam Stapel von Titanenenergie auf. Die Anzahl der pro Sekunde erhaltenen Stapel kann variieren, aber bei einer vollen Aufladung von 120 Stapeln erhöht der summende Kugelkern einen zufälligen Sekundärwert um 128 und Eure Bewegungsgeschwindigkeit um 128 . Hält 20 Sek. lang an." }
entries[405068] = { ["name"] = "Kauterisierende Flamme", ["text"] = "40 Meter ReichweiteKanalisiert (Wirken in 2.5 sek.) 2 min Abklingzeit\nGewährt einem Verbündeten einen Schild in Höhe von 3320 und kanalisiert gleichzeitig einen Strahl aus geschmolzenen Flammen, der dem Verbündeten im Verlauf von 2.5 Sek. [Quellwert] Feuerschaden zufügt. Wenn der Verbündete die Kanalisierung überlebt, wird er um 8301 Gesundheit geheilt.", ["unresolvedValues"] = true }
entries[405069] = { ["name"] = "Überquellende Macht", ["text"] = "Sofort\nWerdet für 15 Sek. zum Berserker. Während 'Berserker' aktiv ist:\n\nErzeugt alle 1.5 Sek. 1 Combopunkt. Fähigkeiten, die Combopunkte generieren, erzeugen 1 zusätzlichen Combopunkt. Finishing-Moves stellen bis zu 3 Combopunkte wieder her, die über das Limit hinaus erzeugt wurden.\n\nAller Angriffs- und Fähigkeitsschaden wird um 15% erhöht." }
