entries[405118] = { ["name"] = "Kondensierender Dampfstein", ["text"] = "30 Meter Reichweite\nSofort\nBeim Erhalten von Heilung besteht eine Chance, Dampf freizusetzen, der bei Euch sowie 2 Verbündeten in der Nähe 623 Gesundheit wiederherstellt." }
entries[405120] = { ["name"] = "Metamorphes Serevitvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nSerevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\n\nErzablagerungen in einem aktiven metamorphen Zustand können nur in der Zaralekhöhle gefunden werden.\n\nGewährt beim Abbauen den folgenden Effekt:\n\nZaralekleuchtstaub :\nBedeckt Euch mit leuchtendem Staub, der perfekt geeignet ist, um die Fortpflanzung von Sporen zu unterstützen. Hält 2 Min. lang an." }
entries[405121] = { ["name"] = "Metamorphes Drakoniumvorkommen", ["text"] = "5 Meter Reichweite\nWirken in 3.2 sek.\nDrakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\nErzablagerungen in einem aktiven metamorphen Zustand können nur in der Zaralekhöhle gefunden werden.\n\nGewährt beim Abbauen den folgenden Effekt:\n\nZaralekleuchtstaub :\nBedeckt Euch mit leuchtendem Staub, der perfekt geeignet ist, um die Fortpflanzung von Sporen zu unterstützen. Hält 2 Min. lang an." }
entries[405122] = { ["name"] = "Krustenverhexung" }
entries[405123] = { ["name"] = "Flackernde Hochblume", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nHochblume ist das häufigste Kraut der Dracheninseln. Es kann so gut wie in jedem Gelände gefunden werden und wächst, wo immer es möglich ist.\n\nFlackernde Kräuter können nur in der Zaralekhöhle gefunden werden.\n\nGewährt beim Sammeln den folgenden Effekt:\n\nZaralekleuchtklette :\nBedeckt Euch mit Leuchtsporen, die sich dringend fortpflanzen wollen. Hält 2 Min. lang an." }
entries[405124] = { ["name"] = "Flackernder Blasenmohn", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nBlasenmohn ist ein empfindliches Kraut, das an feuchten Orten auf den Dracheninseln wächst. Es wächst entlang der Flüsse, Küsten und in feuchten Höhlen.\n\nDie Blasenmohnblume mag einzigartig aussehen, ist aber nicht zu viel zu gebrauchen. Die wässrige Pilzkugel, die sich am Stiel bildet, ist der wertvolle Teil.\n\nFlackernde Kräuter können nur in der Zaralekhöhle gefunden werden.\n\nGewährt beim Sammeln den folgenden Effekt:\n\nZaralekleuchtklette :\nBedeckt Euch mit Leuchtsporen, die sich dringend fortpflanzen wollen. Hält 2 Min. lang an." }
entries[405125] = { ["name"] = "Strahlstrom", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde kanalisiert Hochdruckwellen vor und hinter sich, was Gegnern 12 Frostschaden zufügt und sie zurückstößt.\n\nWährend der Kanalisierung rotieren die Wellen um den Zaubernden herum." }
entries[405126] = { ["name"] = "Flackerndes Steinbrich", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nSteinbrich ist ein widerstandsfähiges Kraut, das an zahlreichen Orten gedeihen kann. Obwohl es allgemein an felsigen Standorten wie Gebirgen oder Klippen auffindbar ist, wächst es auch auf weiten Ebenen oder vereinzelt in vulkanischen Gebieten.\n\nFlackernde Kräuter können nur in der Zaralekhöhle gefunden werden.\n\nGewährt beim Sammeln den folgenden Effekt:\n\nZaralekleuchtklette :\nBedeckt Euch mit Leuchtsporen, die sich dringend fortpflanzen wollen. Hält 2 Min. lang an." }
entries[405127] = { ["name"] = "Flackernde Krümmrinde", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nKrümmrinde ist ein grünliches Kraut, das auf den Dracheninseln gefunden werden kann. Es wächst dort, wo es reichlich Bäume oder Grünpflanzen gibt.\n\nFlackernde Kräuter können nur in der Zaralekhöhle gefunden werden.\n\nGewährt beim Sammeln den folgenden Effekt:\n\nZaralekleuchtklette :\nBedeckt Euch mit Leuchtsporen, die sich dringend fortpflanzen wollen. Hält 2 Min. lang an." }
