entries[405391] = { ["name"] = "Desintegration", ["text"] = "Wirken in 2 sek.\nRionthus zerreißt Spielercharaktere mit Explosionen blauer Magie, was 3 Sek. lang alle 1 Sek. 62076 Zauberfrostschaden verursacht.\n\nDie Magie verbleibt, was betroffene Spielercharaktere um 30% verlangsamt und bewirkt, dass sie 32 Sek. lang Spielercharakteren innerhalb von 5 Metern alle 1 Sek. 28655 Zauberfrostschaden zufügen." }
