entries[405426] = { ["name"] = "Zenimpuls", ["text"] = "40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nErzeugt einen Zenimpuls um einen Verbündeten, der allen Gegnern innerhalb von 8 Metern um das Ziel (165.379% der Zaubermacht) Schaden zufügt. Der Verbündete wird pro getroffenem Gegner um (160% der Zaubermacht) Gesundheit geheilt." }
