entries[405431] = { ["name"] = "Fragmente der Zeit", ["text"] = "100 Meter Reichweite\nWirken in 1.5 sek. 5 sek. Abklingzeit\nMacht sich 8 Sek. lang Zukunft und Vergangenheit zunutze, um Zeitblasen auszustoßen, die sich nach außen bewegen und bei Berührung 4000342 Arkanschaden sowie zusätzlich 6 Sek. lang alle 1 Sek. 1151613 Arkanschaden verursachen. Dieser Effekt ist stapelbar.\n\nDiese Zeitblasen bewegen sich innerhalb des Effektbereichs von ' Zeit zersetzen ' langsamer." }
