entries[405500] = { ["name"] = "Death Knight Blood 10.1 Class Set 4pc", ["text"] = "Wenn Ihr 'Vampirblut' erhalten würdet, werdet Ihr stattdessen mit 'Vampirstärke' erfüllt, was Euch 5 Sek. lang 0.5 Stärke gewährt. Eure Fähigkeiten 'Herzstoß' und 'Siedendes Blut' verlängern die Dauer von 'Vampirstärke' um 10% Sek." }
