entries[405502] = { ["name"] = "Death Knight Frost 10.1 Class Set 4pc", ["text"] = "'Furor des Frostwyrms' lässt getroffene Gegner 12 Sek. lang um 20% erhöhten Schaden durch Eure kritischen Treffer erleiden." }
entries[405503] = { ["name"] = "Death Knight Unholy 10.1 Class Set 2pc", ["text"] = "Der Schaden von 'Todesmantel' und 'Epidemie' ist um 10% erhöht. Der Einsatz von 'Todesmantel' oder 'Epidemie' gewährt einen Stapel von 'Meister des Todes', bis zu 20 Stapel. 'Dunkle Transformation' verbraucht 'Meister des Todes' und gewährt Euch 25 Sek. lang pro Stapel 1% Meisterschaft." }
entries[405504] = { ["name"] = "Death Knight Unholy 10.1 Class Set 4pc", ["text"] = "[ Monstrosität erwecken : 'Monstrosität erwecken' / 'Armee der Toten'] gewährt 20 Stapel von 'Meister des Todes'. Wenn 'Hereinbrechende Verdammnis' durch 'Todesmantel' oder 'Epidemie' verbraucht wird, erhaltet Ihr zusätzlich 1 Stapel von 'Meister des Todes' und 6 Sek. lang 10% Meisterschaft." }
entries[405505] = { ["name"] = "Demon Hunter Havoc 10.1 Class Set 2pc", ["text"] = "Pro 175 verbrauchtem Jähzorn erhaltet Ihr 'Brodelnder Jähzorn', was Eure Beweglichkeit 6 Sek. lang um 10% erhöht." }
entries[405506] = { ["name"] = "Rosie wählen" }
entries[405507] = { ["name"] = "Demon Hunter Havoc 10.1 Class Set 4pc", ["text"] = "Jedes Mal, wenn Ihr 'Brodelnder Jähzorn' erhaltet, erhaltet Ihr 15 Jähzorn und der Schaden Eures nächsten Einsatzes von 'Augenstrahl' wird um 15% erhöht. 5-mal stapelbar." }
entries[405508] = { ["name"] = "Demon Hunter Vengeance 10.1 Class Set 2pc", ["text"] = "Seelenfragmente heilen 10% mehr und das Erzeugen eines Seelenfragments erhöht Euren Feuerschaden 6 Sek. lang um 2%. Mehrere Einsätze können sich überlappen." }
entries[405509] = { ["name"] = "Demon Hunter Vengeance 10.1 Class Set 4pc", ["text"] = "'Abscheren' und 'Fraktur' verursachen Feuerschaden und nachdem 60 Seelenfragmente verzehrt wurden, fügt Eure nächste Anwendung von 'Abscheren' oder 'Fraktur' dem Ziel 3 Sek. lang 'Flammendes Brandmal' zu." }
entries[405510] = { ["name"] = "Druid Balance 10.1 Class Set 2pc", ["text"] = "Der Radius von 'Sonnenfeuer' ist um 3 Meter erhöht. Der Schaden von 'Sonnenfeuer', 'Mondfeuer' und 'Sternschnuppen' ist um 20% erhöht." }
entries[405511] = { ["name"] = "Druid Balance 10.1 Class Set 4pc", ["text"] = "'Sternschnuppen' hat eine Chance von 20%, stattdessen 'Rasender Stern' auszulösen, dem Ziel (81.1% der Zaubermacht) Astralschaden zuzufügen und 5 Astrale Macht zu erzeugen." }
entries[405512] = { ["name"] = "Druid Feral 10.1 Class Set 2pc", ["text"] = "Eure automatischen Angriffe haben eine Chance von 25%, 'Schatten des Raubtiers' zu gewähren, was Eure Beweglichkeit um 1.0% erhöht. Jede Anwendung über 5 hinaus hat eine ansteigende Chance, den Effekt auf 2 Stapel zurückzusetzen.\n(Procchance: 25%, 100ms Abklingzeit)" }
entries[405513] = { ["name"] = "Druid Feral 10.1 Class Set 4pc", ["text"] = "Wenn eine Anwendung von 'Schatten des Raubtiers' die Stapel zurücksetzt, wird Eure Beweglichkeit um 8% erhöht und Ihr erzeugt alle 2 Sek. 1 Combopunkte. Hält 8 Sek. lang an." }
entries[405514] = { ["name"] = "Druid Guardian 10.1 Class Set 2pc", ["text"] = "Wenn Ihr Schaden erleidet, wird der Schaden von 'Zerfleischen' und 'Hauen' sowie die Wuterzeugung 8 Sek. lang um 15% erhöht und Ihr werdet im Verlauf von 8 Sek. um 6% des erlittenen Schadens geheilt." }
entries[405515] = { ["name"] = "Druid Guardian 10.1 Class Set 4pc", ["text"] = "Der Schaden von [ Plätten : 'Plätten' / 'Zermalmen'] ist um 20% erhöht und der Einsatz von 'Eisenfell' oder [ Plätten : 'Plätten' / 'Zermalmen'] erhöht Eure maximale Gesundheit für 12 Sek. um 3%. 5-mal stapelbar." }
entries[405516] = { ["name"] = "Druid Restoration 10.1 Class Set 2pc", ["text"] = "Die Heilung von 'Verjüngung' und 'Blühendes Leben' ist um 10% erhöht. Die regelmäßige Heilung von 'Nachwachsen' ist um 35% erhöht." }
entries[405517] = { ["name"] = "Druid Restoration 10.1 Class Set 4pc", ["text"] = "'Gedeihen' erhöht für zusätzlich 16 Sek. nach seinem Ablauf die Rate Eurer regelmäßigen Heileffekte um 26%. 'Üppige Infusion' bewirkt, dass Eure Heilung bei Eurem Ziel von 'Rasche Heilung' 6 Sek. lang um 15% erhöht wird." }
entries[405518] = { ["name"] = "Evoker Devastation 10.1 Class Set 2pc", ["text"] = "'Desintegration' und 'Scheiterhaufen' durchbohren Gegner mit Obsidiansplittern, die 18% des Schadens als Vulkanschaden über 8 Sek. verursachen." }
entries[405519] = { ["name"] = "Evoker Devastation 10.1 Class Set 4pc", ["text"] = "Ermächtigungszauber verursachen 12% mehr Schaden und lassen Eure Obsidiansplitter mit Macht lodern, wodurch diese 5 Sek. lang 200% mehr Schaden verursachen. Während 'Drachenwut' lodern Eure Splitter immer mit Macht." }
entries[405520] = { ["name"] = "Evoker Preservation 10.1 Class Set 2pc", ["text"] = "'Geisterblüte' wendet einen regelmäßigen Heileffekt von 40% der hervorgerufenen Heilung über 8 Sek. an. 'Traumatem' ruft 15% mehr Heilung hervor." }
entries[405521] = { ["name"] = "Herdtotem von Morqut", ["text"] = "Wirken in 5 sek.\nTeleportiert den Zaubernden zum Morqutdorf. Kann nur auf der Verbotenen Insel aktiviert werden." }
entries[405522] = { ["name"] = "Evoker Preservation 10.1 Class Set 4pc", ["text"] = "Nachdem Ihr 4 Ermächtigungszauber gewirkt habt, erhaltet Ihr eine 'Essenzexplosion' sofort und eine weitere 3 Sek. später." }
entries[405523] = { ["name"] = "Glibbi wählen" }
entries[405524] = { ["name"] = "Hunter Beast Mastery 10.1 Class Set 2pc", ["text"] = "Erhöht den Schaden von 'Kobraschuss' und 'Tötungsbefehl' um 15%." }
entries[405525] = { ["name"] = "Hunter Beast Mastery 10.1 Class Set 4pc", ["text"] = "'Kobraschuss', 'Tötungsbefehl' und 'Mehrfachschuss' verringern die Abklingzeit von 'Zorn des Wildtiers' um 2.0 Sek." }
entries[405526] = { ["name"] = "Hunter Marksmanship 10.1 Class Set 2pc", ["text"] = "[ Schimärenschuss : 'Schimärenschuss' / 'Arkaner Schuss'] und 'Mehrfachschuss' verursachen 10% mehr Schaden und haben eine Chance von 8%, den Effekt von 'Todesstoß' zu gewähren.\n(Procchance: 8%)" }
entries[405527] = { ["name"] = "Hunter Marksmanship 10.1 Class Set 4pc", ["text"] = "'Tödlicher Schuss' verursacht 15% mehr Schaden und verringert die Abklingzeit von 'Gezielter Schuss' und 'Schnellfeuer' um 1.5 Sek." }
entries[405528] = { ["name"] = "Hunter Survival 10.1 Class Set 2pc", ["text"] = "'Lauffeuerbombe' verursacht 10% mehr Schaden und erhöht den Schaden Eures nächsten Einsatzes von 'Tötungsbefehl' um 40%." }
entries[405529] = { ["name"] = "Gregg wählen" }
entries[405530] = { ["name"] = "Hunter Survival 10.1 Class Set 4pc", ["text"] = "Verringert die Abklingzeit von ' Lauffeuerbombe' pro 30 verbrauchtem Fokus um 1.0 Sek." }
entries[405531] = { ["name"] = "Explosion", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nÜberzieht das Ziel mit Feuerschaden." }
entries[405532] = { ["name"] = "Mage Arcane 10.1 Class Set 2pc", ["text"] = "'Arkane Woge' erhöht den Zauberschaden um zusätzlich 10% und der Effekt hält 3 Sek. länger an." }
entries[405533] = { ["name"] = "Mage Arcane 10.1 Class Set 4pc", ["text"] = "Pro 420000 Mana, das Ihr für und während 'Arkane Woge' verbraucht, wird Euer Zauberschaden für 18 Sek. nach dem Ablauf von 'Arkane Woge' um 1.0% erhöht. Bis zu 25-mal stapelbar. Die Manaregeneration ist währenddessen um 50% erhöht." }
entries[405534] = { ["name"] = "Mage Fire 10.1 Class Set 2pc", ["text"] = "'Phönixflammen' belegt alle Gegner, die durch den Zauber Schaden erleiden, mit 'Verkohlende Glut', was ihren durch Euch erlittenen Schaden 14 Sek. lang um 6% erhöht." }
entries[405535] = { ["name"] = "Mage Fire 10.1 Class Set 4pc", ["text"] = "Wenn Eure direkten Schadenszauber 25-mal einen Gegner treffen, der mit 'Verkohlende Glut' belegt ist, verursachen Eure nächsten 2 'Phönixflammen' 100% mehr Schaden und erstatten eine Aufladung." }
entries[405536] = { ["name"] = "Mage Frost 10.1 Class Set 2pc", ["text"] = "Der Schaden von 'Hagel' und 'Eislanze' ist um 20% erhöht. Euer Zauber 'Hagel' löst beim Einschlag eine Explosion aus, die Gegnern in der Nähe 35% seines Schadens zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[405538] = { ["name"] = "Mage Frost 10.1 Class Set 4pc", ["text"] = "Wenn Ihr 'Eislanze' gegen ein eingefrorenes Ziel einsetzt, besteht eine Chance von 10%, 'Hirnfrost' auszulösen." }
entries[405539] = { ["name"] = "Monk Brewmaster 10.1 Class Set 2pc", ["text"] = "Der Schaden von 'Blackout-Tritt' ist um 20% erhöht. Ihr habt eine Chance von 10%, Eure Stapel von 'Flüchtiger Kämpfer' bei erfolgreichem Ausweichen nicht zurückzusetzen." }
entries[405540] = { ["name"] = "Monk Brewmaster 10.1 Class Set 4pc", ["text"] = "'Tritt der aufgehenden Sonne' gewährt einen Stapel von 'Flüchtiger Kämpfer'. Wenn Ihr ausweicht, werden der Schaden und die kritische Trefferchance Eures nächsten Einsatzes von 'Wirbelnder Kranichtritt' oder 'Tritt der aufgehenden Sonne' um 5% erhöht. Bis zu 5-mal stapelbar." }
entries[405541] = { ["name"] = "Monk Mistweaver 10.1 Class Set 2pc", ["text"] = "Heilung von 'Erneuernder Nebel', 'Beruhigender Nebel' und 'Einhüllender Nebel' um 12 erhöht." }
entries[405542] = { ["name"] = "Monk Mistweaver 10.1 Class Set 4pc", ["text"] = "Das Trinken von Tee erhöht die Heilung von 'Beleben' und 'Erneuernder Nebel' 6 Sek. lang um 40%." }
entries[405543] = { ["name"] = "Monk Windwalker 10.1 Class Set 2pc", ["text"] = "'Tritt der aufgehenden Sonne' verursacht 5% mehr Schaden und erzeugt eine Nova, die allen Gegnern innerhalb von 8 Metern (83% der Angriffskraft) Schattenflammenschaden zufügt." }
entries[405544] = { ["name"] = "Monk Windwalker 10.1 Class Set 4pc", ["text"] = "Ca. 2 Procs pro Minute\nEure automatischen Nahkampfangriffe haben eine Chance, einen Schattenflammengeist auf Euren Gegner zu hetzen, der 7.5 Sek. lang Eure Fähigkeiten bei 20% Effektivität kopiert." }
entries[405545] = { ["name"] = "Paladin Holy 10.1 Class Set 2pc", ["text"] = "Kritische Treffer durch 'Heiliger Schock' heilen 80% mehr Gesundheit und verringern die Abklingzeit von 'Hammer des Lichts' um 2 Sek. oder 'Heiliges Prisma' um 1.0 Sek." }
entries[405546] = { ["name"] = "Paladin Holy 10.1 Class Set 4pc", ["text"] = "'Hammer des Lichts' heilt 100% häufiger und erzeugt alle 4 Sek. 1 Heilige Kraft. Die Heilung von 'Heiliges Prisma' ist um 40% erhöht und die Fähigkeit erzeugt 1 Heilige Kraft beim Einsatz auf ein gegnerisches Ziel oder 3 beim Einsatz auf einen Verbündeten." }
entries[405547] = { ["name"] = "Paladin Protection 10.1 Class Set 2pc", ["text"] = "'Schild des Rächers' lässt getroffene Ziele mit 'Herzensfeuer' brennen, was zusätzlich 20% des verursachen Schadens im Verlauf von 5 Sek. verursacht. 'Herzensfeuer' heilt Euch um 100% seines verursachten Schadens." }
entries[405548] = { ["name"] = "Paladin Protection 10.1 Class Set 4pc", ["text"] = "Kritische Treffer durch 'Richturteil' wenden 'Herzensfeuer' an und können 'Oberster Kreuzfahrer' auslösen." }
entries[405549] = { ["name"] = "Paladinklassenset 10.1, Vergeltung, 2 Teile", ["text"] = "'Richturteil' und 'Hammer des Zorns' verursachen 10% mehr Schaden und 15% mehr kritischen Schaden. 'Hammer des Zorns' wendet 'Richturteil' auf Gegner an." }
entries[405550] = { ["name"] = "Paladinklassenset 10.1, Vergeltung, 4 Teile", ["text"] = "'Richturteil' erhöht den Schaden, den Gegner durch Eure Heilige Kraft verbrauchenden Fähigkeiten erleiden, um zusätzlich 15%. 'Hammer des Zorns' fügt jetzt 4 Zielen in der Nähe 20% seines Schadens zu." }
entries[405551] = { ["name"] = "Priest Discipline 10.1 Class Set 2pc", ["text"] = "Der Schaden von [ Läuterung des Bösen : 'Läuterung des Bösen' / 'Schattenwort: Schmerz'] wird um 25% erhöht. Die Heilung von 'Machtwort: Glanz' wird um 15% erhöht." }
entries[405552] = { ["name"] = "Kampfbereit" }
entries[405553] = { ["name"] = "Priest Discipline 10.1 Class Set 4pc", ["text"] = "Wenn ein Ziel durch 'Machtwort: Glanz' mit 'Abbitte' belegt wird, hält der Effekt 3 Sek. länger an. Eure Zauber haben eine Chance, Euer nächstes 'Machtwort: Glanz' zu einem Spontanzauber zu machen und seine Manakosten um 50% zu verringern. Kann bis zu 2 Aufladungen ansammeln." }
entries[405554] = { ["name"] = "Priest Holy 10.1 Class Set 2pc", ["text"] = "Wenn Ihr 'Gebet der Besserung' wirkt, besteht eine Chance von 35%, dass der Effekt auf einen weiteren Verbündeten kopiert wird." }
entries[405555] = { ["name"] = "Wasserbombe", ["text"] = "100 Meter Reichweite\nSofort 8 sek. Abklingzeit\nSchleudert eine massive Kugel aus Wasser, die alle Feuer in der Nähe löscht." }
entries[405556] = { ["name"] = "Priest Holy 10.1 Class Set 4pc", ["text"] = "Wenn 'Gebet der Besserung' springt oder abläuft, erhöht es den Schaden und die Heilung Eures nächsten Segensworts um 4%. Dieser Effekt ist bis zu 15-mal stapelbar." }
entries[405557] = { ["name"] = "Priest Shadow 10.1 Class Set 2pc", ["text"] = "Erhöht die Chance, dass 'Schattenhafte Einsicht' ausgelöst wird, um 25%. 'Gedankenschlag' verursacht beim Verbrauchen von 'Schattenhafte Einsicht' 40% mehr Schaden und erzeugt 4 mehr Wahnsinn." }
entries[405558] = { ["name"] = "Priest Shadow 10.1 Class Set 4pc", ["text"] = "Der Schaden von 'Verschlingende Seuche' ist um 18% erhöht. Jeder 4. Einsatz von 'Verschlingende Seuche' erhöht den Schaden von schattenhaften Erscheinungen, die innerhalb der nächsten 10 Sek. beschworen werden, um 100%." }
entries[405559] = { ["name"] = "Rogue Assassination 10.1 Class Set 2pc", ["text"] = "'Blutung' verursacht zusätzlich 40% Schaden als Naturschaden. 'Blutroter Sturm' verursacht zusätzlich 20% Schaden als Naturschaden." }
entries[405560] = { ["name"] = "Rogue Assassination 10.1 Class Set 4pc", ["text"] = "Erhöht Euren verursachten Naturschaden 30 Sek. lang um 40%, wenn 'Todesmal' ausläuft." }
entries[405561] = { ["name"] = "Rogue Outlaw 10.1 Class Set 2pc", ["text"] = "Schaden, den Ihr verursacht, wendet einen 'Seelenriss' an, der 5% Eures gesamten Schadens im Verlauf von 8 Sek. als körperlichen Schaden verursacht." }
entries[405562] = { ["name"] = "Rogue Outlaw 10.1 Class Set 4pc", ["text"] = "'Zwischen die Augen' entfesselt jeden 'Seelenriss', wodurch Ihr 200% des verbleibenden Schadens verursacht und 15 Sek. lang 5% Beweglichkeit erhaltet." }
entries[405563] = { ["name"] = "Rogue Subtlety 10.1 Class Set 2pc", ["text"] = "'Schattentanz' gewährt Euch 6 Sek. lang 'Symbole des Todes' und verlängert die Dauer von 'Blutung' um 4 Sek." }
entries[405564] = { ["name"] = "Rogue Subtlety 10.1 Class Set 4pc", ["text"] = "'Symbole des Todes' erhöht den kritischen Schaden von 'Ausweiden' und 'Schwarzpulver' um 40%." }
entries[405565] = { ["name"] = "Shaman Elemental 10.1 Class Set 2pc", ["text"] = "Erhaltet alle 50 Sek. 'Sturmhüter'." }
entries[405566] = { ["name"] = "Shaman Elemental 10.1 Class Set 4pc", ["text"] = "Nachdem Ihr Sturmhüter verbraucht habt, erzeugen Eure 'Blitzschläge', 'Lavaeruptionen', 'Eisfurore' und 'Frostschocks' 8 Sek. lang 50% mehr Mahlstrom und Eure 'Kettenblitzschläge', 'Lavastrahle' und 'Erdbeben' verursachen 20% mehr kritischen Schaden." }
entries[405567] = { ["name"] = "Shaman Enhancement 10.1 Class Set 2pc", ["text"] = "'Zerschlagung' erhöht Eure Meisterschaft 15 Sek. lang um (12 * 2 )%." }
entries[405568] = { ["name"] = "Shaman Enhancement 10.1 Class Set 4pc", ["text"] = "'Zerschlagung' erhöht Euren körperlichen und Feuerschaden 15 Sek. lang um 20% und Eure nächsten 2 Einsätze von 'Kettenblitzschlag' verursachen 20% mehr Schaden und erstatten 50% der verbrauchten Aufladungen von 'Waffe des Mahlstroms' zurück." }
entries[405569] = { ["name"] = "Shaman Restoration 10.1 Class Set 2pc", ["text"] = "Wenn Ihr 'Heilender Regen' wirkt, wird jeder mit Eurer 'Springflut' belegte Verbündete durch 'Flutwasser' um (322% der Zaubermacht) Gesundheit flächengeheilt." }
entries[405570] = { ["name"] = "Shaman Restoration 10.1 Class Set 4pc", ["text"] = "Jeder Verbündete, der durch 'Flutwasser' geheilt wird, erhöht 8 Sek. lang Eure hervorgerufene Heilung um 1.0% sowie die Heilung Eures nächsten Einsatzes von 'Welle der Heilung' oder 'Heilende Woge' um 10% oder von 'Kettenheilung' um 2%." }
entries[405571] = { ["name"] = "Warlock Affliction 10.1 Class Set 2pc", ["text"] = "Verringert die Abklingzeit von 'Übler Makel' um 5 Sek., die Abklingzeit von 'Phantomsingularität' um 12 Sek. und erhöht deren Schaden um 60%." }
entries[405572] = { ["name"] = "Warlock Affliction 10.1 Class Set 4pc", ["text"] = "Gegner, die durch 'Phantomsingularität' Schaden erleiden, erhalten während seiner Dauer 'Schwäche' und Gegner, die durch 'Übler Makel' Schaden erleiden, erhalten 10 Sek. lang 'Schwäche'. 'Schwäche' erhöht den erlittenen Schaden um 10%." }
entries[405573] = { ["name"] = "Warlock Demonology 10.1 Class Set 2pc", ["text"] = "'Dämonenblitz' verursacht 20% mehr Schaden. Der Verbrauch eines 'Dämonischen Kerns' verringert die Abklingzeit von 'Grimoire: Teufelswache' um 0.5 Sek." }
entries[405574] = { ["name"] = "Warlock Demonology 10.1 Class Set 4pc", ["text"] = "Der Schaden von 'Grimoire: Teufelswache' ist um 20% erhöht. Während 'Grimoire: Teufelswache' aktiv ist, verursachen all Eure Dämonen 20% mehr Schaden." }
entries[405575] = { ["name"] = "Warlock Destruction 10.1 Class Set 2pc", ["text"] = "Blitze von 'Dämonenfeuer kanalisieren', 'Feuerbrand' und 'Verbrennen' haben eine Chance, einen zusätzlichen Dämonenfeuerblitz zu verschießen. Diese Blitze fügen ihrem Primärziel 50% mehr Schaden zu." }
entries[405576] = { ["name"] = "Warlock Destruction 10.1 Class Set 4pc", ["text"] = "Blitze von 'Dämonenfeuer' erhöhen Euren verursachten Feuerschaden 13 Sek. lang um 1.0%. Bis zu 8-mal stapelbar. Das Hinzugewinnen eines Stapels setzt die Effektdauer nicht zurück. Das Wirken von 'Dämonenfeuer kanalisieren' setzt diesen Effekt zurück." }
entries[405577] = { ["name"] = "Kriegerklassenset 10.1, Waffen, 2 Teile", ["text"] = "'Tiefe Wunden' erhöht Eure kritische Trefferchance und den an betroffenen Zielen verursachten kritischen Schaden um 5%." }
entries[405578] = { ["name"] = "Kriegerklassenset 10.1, Waffen, 4 Teile", ["text"] = "Bei kritischen Treffern durch 'Tiefe Wunden' besteht eine Chance, dass der Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' um 10% erhöht wird und dieser Einsatz Gegnern vor Euch [(19.32% der Angriffskraft) * 2] körperlichen Schaden zufügt. Bis zu 3-mal stapelbar. Der Schaden ist bei über 5 Zielen verringert.\n(2s Abklingzeit)" }
entries[405579] = { ["name"] = "Kriegerklassenset 10.1, Furor, 2 Teile", ["text"] = "Erhöht den Schaden und die kritische Trefferchance von 'Toben' um 15%." }
entries[405580] = { ["name"] = "Kriegerklassenset 10.1, Furor, 4 Teile", ["text"] = "'Toben' bewirkt, dass Euer nächster 'Blutdurst' eine um 12% erhöhte kritische Trefferchance hat, 35% mehr Schaden verursacht und 2 zusätzliche Wut erzeugt. Bis zu 10-mal stapelbar." }
entries[405581] = { ["name"] = "Kriegerklassenset 10.1, Schutz, 2 Teile", ["text"] = "'Schildschlag' verursacht 15% mehr Schaden und verringert die Abklingzeit von 'Letztes Gefecht' um 2 Sek. Während 'Letztes Gefecht' sind diese Effekte verdoppelt." }
entries[405582] = { ["name"] = "Kriegerklassenset 10.1, Schutz, 4 Teile", ["text"] = "Für 20 Sek. nachdem 'Letztes Gefecht' endet, entfesselt 'Schildschlag' eine Kraftwelle, die Gegnern vor Euch (135% der Angriffskraft) körperlichen Schaden zufügt und ihren Euch zugefügten Schaden 5 Sek. lang um 5% verringert." }
