entries[405807] = { ["name"] = "Shaohaos Lektion - Zorn", ["text"] = "Sofort\nJedes Mal, wenn Ihr 'Sheiluns Gabe' einsetzt, lernt Ihr eine von Shaohaos Lektionen für bis zu 30 Sek., wobei die Dauer davon abhängt, wie viele Nebelwolken verbraucht werden.\n\nLektion des Zweifels : Erhöht Schaden und Heilung Eurer Zauber und Fähigkeiten abhängig von der aktuellen Gesundheit des Ziels um bis zu 40%.\n\nLektion der Verzweiflung : Euer kritischer Trefferwert ist um 30% erhöht, solange Ihr über mehr als 50% Gesundheit verfügt.\n\nLektion der Angst : Verringert Euren erlittenen Schaden um 15% und erhöht Euer Tempo um 20%.\n\nLektion des Zorns : Alle 4 Sek. werden 25% des von Euch verursachten Schadens oder der von Euch hervorgerufenen Heilung dupliziert." }
entries[405808] = { ["name"] = "Shaohaos Lektion - Zweifel", ["text"] = "Sofort\nJedes Mal, wenn Ihr 'Sheiluns Gabe' einsetzt, lernt Ihr eine von Shaohaos Lektionen für bis zu 30 Sek., wobei die Dauer davon abhängt, wie viele Nebelwolken verbraucht werden.\n\nLektion des Zweifels : Erhöht Schaden und Heilung Eurer Zauber und Fähigkeiten abhängig von der aktuellen Gesundheit des Ziels um bis zu 40%.\n\nLektion der Verzweiflung : Euer kritischer Trefferwert ist um 30% erhöht, solange Ihr über mehr als 50% Gesundheit verfügt.\n\nLektion der Angst : Verringert Euren erlittenen Schaden um 15% und erhöht Euer Tempo um 20%.\n\nLektion des Zorns : Alle 4 Sek. werden 25% des von Euch verursachten Schadens oder der von Euch hervorgerufenen Heilung dupliziert." }
