entries[405819] = { ["name"] = "Sengendes Schmettern", ["text"] = "100 Meter Reichweite\nSofort\nRashok springt auf einen anvisierten Spielercharakter zu und schmettert auf den Boden, was an dieser Position einen Lavavortex auslöst und allen Spielercharakteren 205328 Feuerschaden zufügt. Dieser Schaden wird pro Lavavortex in der Kammer um 20% erhöht.\n\nDer Aufprall des Schmetterns bewirkt, dass jeder Lavavortex ' Lavawelle ' ausstößt.\n\nEine Lavaexplosion bricht aus, wenn ' Sengendes Schmettern ' einen Lavavortex trifft.\n\nVon ' Sengendes Schmettern ' getroffene Schattenflammenenergie wird zerstört." }
entries[405821] = { ["name"] = "Sengendes Schmettern", ["text"] = "200 Meter Reichweite\nWirken in 5 sek.\nRashok springt auf einen anvisierten Spielercharakter zu und schmettert auf den Boden, was an dieser Position einen Lavavortex auslöst und allen Spielercharakteren 205328 Feuerschaden zufügt. Dieser Schaden wird pro Lavavortex in der Kammer um 20% erhöht.\n\nDer Aufprall des Schmetterns bewirkt, dass jeder Lavavortex ' Lavawelle ' ausstößt.\n\nEine Lavaexplosion bricht aus, wenn ' Sengendes Schmettern ' einen Lavavortex trifft.\n\nVon ' Sengendes Schmettern ' getroffene Schattenflammenenergie wird zerstört." }
