entries[405830] = { ["name"] = "Schattenflammenatem", ["text"] = "Sofort\nAtmet Flammen in die Richtung des aktuellen Ziels innerhalb von 45 Metern und fügt Spielercharakteren in einem kegelförmigen Bereich vor dem Zaubernden 3 Sek. lang alle 1 Sek. 25 Schattenflammenschaden zu." }
