entries[405832] = { ["name"] = "Stinkender heller Trank", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTobende Luft , Tobender Verfall , Zaralekleuchtsporen (50), Steinbrich (2), Drakonische Phiole (5)\nOptionale Reagenzien:\nAlchemistischer Katalysator (#91)\nDieses widerwärtige Rezept erfordert einen mit mächtiger Verfallsmagie erfüllten Altar, den es angeblich tief in der Brackenfellhöhle geben soll.\nVerkäufer:\nNeblie\nZone:\nZaralekhöhle\nKosten:\n1\n\nToxisch\nBenutzen: Erhellt die Welt um Euch herum.\n\"Mischt zwei Teile zerstampftes Steinbrich mit einem Teil reinen Verfall und gebt ein paar mysteriöse Sporen dazu, um den Anwender auf Trab zu halten.\"" }
entries[405833] = { ["name"] = "Leere zwischen den Sternen", ["text"] = "300 Meter Reichweite\nSofort\nDas Ziel ist allein in der unendlichen Weite des Weltraums gestrandet, was den verursachten Schaden um 99% verringert. Wenn das Ziel nach 20 Sek. die Fragmente seines Verstandes noch nicht wiedergefunden hat, ist es für immer verloren und stirbt." }
entries[405834] = { ["name"] = "Verbessertes Schleichen", ["text"] = "Wenn 'Krallenhieb' aus der Verstohlenheit heraus eingesetzt wird, wird das Ziel für 4 Sek. betäubt und die Fähigkeit verursacht 60% mehr Schaden.\n\nWenn 'Schreddern' aus der Verstohlenheit heraus eingesetzt wird, verursacht die Fähigkeit 60% mehr Schaden und die kritische Trefferchance ist verdoppelt." }
entries[405835] = { ["name"] = "Lodernder Speer", ["text"] = "100 Meter Reichweite\nWirken in 3.4 sek.\nDer Jäger nimmt mehrere Spielercharaktere ins Visier und schleudert ' Lodernder Speer ' auf sie, was Spielercharakteren innerhalb von 6 Metern um den Einschlag sofort 238844 körperlichen Schaden zufügt.\n\n' Lodernder Speer ' verbleibt im Boden und explodiert kurz darauf, was allen Spielercharakteren innerhalb von 8 Metern 286504 Feuerschaden zufügt." }
