entries[405847] = { ["name"] = "Transmutieren: Dracothyst", ["text"] = "Wirken in 3 sek. 1 tag Wiederaufladung\n7 Aufladungen\nReagenzien:\nZaralekleuchtsporen (300), Seidiger Juwelenstaub (50)\nVerkäufer:\nNeblie\nZone:\nZaralekhöhle\nKosten:\n1\n\nDracothyst\nHandwerksmaterial\n\"Ein mächtiger Kristall, der magische Energien halten kann. Kann durch alchemische Transmutationen hergestellt sowie im Auktionshaus verkauft und erworben werden.\"" }
