entries[405879] = { ["name"] = "Kessel der entzogenen Fäulnis", ["text"] = "Wirken in 3 sek.\nReagenzien:\nErweckter Verfall (3), Zaralekleuchtsporen (200), Dracothyst , Verwesungsresistenter Kessel\nNimmt vorsichtig zersetzte Exemplare vom Altar des Verfalls in der Brackenfellhöhle, um sie später zu verwenden.\nBeute von:\nWeltkreaturen\n\nSammeln von:\nMit Moder bedeckte Kiste\nZone:\nAzurblaues Gebirge\nZone:\nThaldraszus\n\nKessel der entzogenen Fäulnis\nWird beim Aufheben gebunden\nBenutzen: Stellt für 10 Min. den Kessel der entzogenen Fäulnis auf, der Euch die Herstellung von Rezepten erlaubt, die den Altar des Verfalls benötigen.\n\nWenn alle Aufladungen verbraucht sind, könnt Ihr den verwesungsresistenten Kessel wiederverwenden. (10 Min Abklingzeit)\n3 Aufladungen\n70" }
