entries[405887] = { ["name"] = "Verbrannte Erde", ["text"] = "Unbegrenzte Reichweite\nSofort\nZornauge atmet eine Wolke aus Verfall aus, die Spielercharakteren vor ihr 40 Naturschaden zufügt. Die Fäulnis verdichtet sich zu einer wandernden Wolke, die Spielercharakteren im Effektbereich alle 2 Sek. 11 Naturschaden zufügt, sie zum Schweigen bringt und mit ' Verwelkende Fäulnis ' belegt." }
