entries[405892] = { ["name"] = "Kessel der entzogenen Fäulnis", ["text"] = "Wirken in 2 sek. 10 min Abklingzeit\nStellt für 10 Min. den Kessel der entzogenen Fäulnis auf, der Euch die Herstellung von Rezepten erlaubt, die den Altar des Verfalls benötigen.\n\nWenn alle Aufladungen verbraucht sind, könnt Ihr den verwesungsresistenten Kessel wiederverwenden." }
