entries[405924] = { ["name"] = "Chronotasche", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nErschafft eine Tasche mit verlangsamter Zeit, die Bewegungsgeschwindigkeit und Tempo aller Spielercharaktere darin um 30% verringert.\n\nJeder Spielercharakter, der die Tasche verlässt, wird von einem ' Chronorückstoß ' getroffen und erleidet 119377 Arkanschaden." }
