entries[405926] = { ["name"] = "Temporalrausch", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nChronikar stürmt durch die Raumzeit auf den Standort eines Spielercharakters zu, was Spielercharakteren in ihrer Bahn 50 Arkanschaden zufügt und sie wegstößt.\n\nDann kehrt sie die Raumzeit um, wodurch sie sich zum Spielercharakter zurückteleportiert, den sie ursprünglich angegriffen hat, und schlägt mit ' Temporales Abscheren ' zu." }
