entries[405937] = { ["name"] = "Trainingsmatrix der Titanen V", ["text"] = "Wirken in 3 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nChromatischer Staub (10), Pulsierender Splitter , Ermächtigter Flugstein\nBeute von:\nZaralekhöhle\n\nSchatz:\nZaralekhöhle\n\nTrainingsmatrix der Titanen V\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+150 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Leider kann man kaum in Worte fassen, was die Titanenmatrix ist. Man muss sie einfach selbst gesehen haben.\"" }
