entries[406108] = { ["name"] = "Schattenflammenwappen des verzauberten Welpen", ["text"] = "Wirken in 3 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nChromatischer Staub (30), Pulsierender Splitter (5), Resonierender Kristall , Schattenflammenwappen des Welpen\nNach dem Verschwinden der Schattenflammenwappen ist dieses Rezept beinahe unmöglich herzustellen.\nBeute von:\nZaralekhöhle\n\nSchatz:\nZaralekhöhle\n\nSchattenflammenwappen des verzauberten Welpen\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+160 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"" }
