entries[406152] = { ["name"] = "Verdammnisflammen", ["text"] = "200 Meter Reichweite\nSofort\nRashok verschießt eine Salve aus Schattenflammengeschossen durch die Kammer. Jedes Geschoss fügt allen Spielercharakteren innerhalb von 5 Metern um seinen Einschlagsort 143173 Schattenflammenschaden sowie 8 Sek. lang alle 1 Sek. 71626 Schattenflammenschaden zu. Dieser Effekt ist stapelbar.\n\nJedes Geschoss, das keinen Spielercharakter trifft, fügt allen Spielercharakteren 285940 Schattenflammenschaden zu." }
