entries[406165] = { ["name"] = "Schwelende Wut", ["text"] = "100 Meter Reichweite\nWirken in 0.75 sek.\nRashok brüllt vor Schmerz und fügt allen Spielercharakteren 23875 Schattenflammenschaden zu, während er sich aus der Ältestenleitung befreit.\n\nRashoks innere Flamme schwelt, während er sich aus seinem Gefängnis befreit, was den Schaden von ' Sengende Hitzewelle ' um 500% erhöht." }
entries[406172] = { ["name"] = "Uralter Zorn", ["text"] = "200 Meter Reichweite\nSofort\nWenn er 100 Energie erreicht, wird Rashok immun gegen die Ältestenleitung und überlädt sich mit pulsierenden Flammen. Fügt allen Spielercharakteren alle 1 Sek. 716259 Schattenflammenschaden zu." }
