entries[406266] = { ["name"] = "Schulterschützer der Sporenkolonie", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nZaralekleuchtsporen (150), Widerstandsfähiges Leder (200), Steinkrustenbalg (18), Funke (#247)\nOptionale Reagenzien:\nDieses widerwärtige Rezept erfordert einen mit mächtiger Verfallsmagie erfüllten Altar, den es angeblich tief in der Brackenfellhöhle geben soll.\nVerkäufer:\nGarram\nZone:\nZaralekhöhle\nKosten:\n1\n\nSchulterschützer der Sporenkolonie\nWird beim Aufheben gebunden\nSchulter Leder\n258 Rüstung\n+193 [Beweglichkeit oder Intelligenz]+312 Ausdauer\nErhöht Eure kritische Trefferwertung um + 179.\nErhöht Eure Tempowertung um + 179.\nHaltbarkeit 100 / 100\nAnlegen: Wenn Ihr mit Zaubern und Fähigkeiten Schaden verursacht, habt Ihr eine Chance, Euer Ziel mit einem Stapel 'Ewig verfallende Sporen' zu belegen. Bei 5 Stapeln verfallen die Sporen rapide, was ( 776 * 10) Naturschaden im Verlauf von 10 Sek. verursacht.\n\nManchmal verfallen die Sporen sofort und fügen Euch 776 Naturschaden zu.\n\nDieser Effekt erhöht sich um 100%, wenn Ihr einen Gegenstand ausgerüstet habt, der mit einem giftigen Rüstungsflicken hergestellt wurde.\n70" }
entries[406267] = { ["name"] = "Adaptive Dracothystarmschützer", ["text"] = "Wirken in 2 sek. 3\nReagenzien:\nDracothyst , Obsidiankobrahaut , Adamantschuppen (150), Erdschimmerschuppen (10), Funke (#247)\nOptionale Reagenzien:\nVerkäufer:\nGarram\nZone:\nZaralekhöhle\nKosten:\n1\n\nAdaptive Dracothystarmschützer\nWird beim Aufheben gebunden\nHandgelenk Kette\n277 Rüstung\n+144 [Beweglichkeit oder Intelligenz]+234 Ausdauer\nErhöht Eure Tempowertung um + 134.\nErhöht Eure Meisterschaftswertung um + 134.\nHaltbarkeit 55 / 55\nAnlegen: Ihr passt Euch gelegentlich für 12 Sek. Eurer aktuellen Situation an.\n\nSchaden zu erleiden, kann Eure Vielseitigkeit und Euren kritischen Trefferwert um 170 erhöhen.\n\nKritischen Schaden oder Heilung zu verursachen, kann Eure Meisterschaft und Euer Tempo um 170 erhöhen.\n70" }
